ALTER TABLE agent_run DROP CONSTRAINT ck_agent_run_hold_reason;
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_hold_reason
    CHECK (hold_reason IS NULL OR hold_reason IN ('BUDGET', 'SANDBOX_ROOM', 'MODEL_POOL'));

changeSet.rollback:
UPDATE agent_run SET hold_reason = NULL, available_at = LEAST(available_at, clock_timestamp()) WHERE hold_reason = 'MODEL_POOL';
ALTER TABLE agent_run DROP CONSTRAINT ck_agent_run_hold_reason;
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_hold_reason
