changeSet.sql:
CREATE FUNCTION public.scm_credential_is_active(p_connection_id bigint, p_generation bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER
RETURN EXISTS (
    SELECT 1 FROM public.connection c
    WHERE c.id = p_connection_id AND c.credentials_generation = p_generation AND c.state = 'ACTIVE'
);
